<template>
  <button
    ref="component"
    :class="Class"
    class="vs-button vs"
    v-bind="$props"
    v-on="Listeners"
  >
    <span ref="spanx">
      <slot
        v-if="!iconAfter"
        name="icon"
      />

      <slot />

      <slot
        v-if="iconAfter"
        name="icon"
      />
    </span>
  </button>
</template>
<script>
import globalProps from '../../vuesax/util/props'
import { setColor } from '../../vuesax/util/functions'
export default {
  name: 'VsButton',
  mixins: [globalProps],
  inheritAttrs: false,
  props:{
    active: {
      default: false,
      type: Boolean
    },
    submit: {
      default: false,
      type: Boolean
    },
    iconAfter:{
      default: false,
      type: Boolean
    },
    textColor: {
      default: null,
      type: String
    },
    to:{
      default: null,
      type: String
    },
    href:{
      default: null,
      type:String
    },
    blank:{
      default:false,
      type:Boolean
    }
  },

  computed: {
    Class() {
      return [
        { 'vs-button__active' : this.active },
        { 'vs-button__disabled' : this.disabled },
        { 'vs-button__loading' : this.loading },
        { 'vs-button__submit' : this.submit },
        `vs-button--${this.size}`,
        `vs-button--${this.$vsTheme}`,
        `vs-button--${this.kind}`,
        this.$vsGlobalClass,
      ]
    },
    Listeners() {
      return {
        ...this.$listeners,
        click: () => {
          this.handleClick()
        },
        mouseenter: (evt) => {
          /*
          * Agrgegando efecto de sticky design al componente
          */
          this.$stickyMove(evt,'span', true)
          this.$emit('mouseenter', evt)
        },
      }
    }
  },

  watch:{
    textColor() {
      if(this.textColor) {
        setColor('text-color', this.textColor, this.$refs.component)
      }
    }
  },

  mounted () {
    if(this.textColor) {
      setColor('text-color', this.textColor, this.$refs.component)
    }
  },

  methods:{
    handleClick() {
      this.$emit('click',event)
      if(this.to) {
        this.routerPush()
      } else if (this.href) {
        this.openHref()
      }
    },
    routerPush() {
      this.$router.push(this.to)
    },
    openHref() {
      this.blank ? window.open(this.href) : window.location.href = this.href
    }
  }
}
</script>

<style lang="stylus">
  @import "../../vuesax/style/imports"
  @import "./main"
</style>
